using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.IO;using ZenQOffice.UI;using ZenQOffice.Core;using ZenQOffice.Format;
class Test{static void Check(bool b,string m){if(!b)throw new Exception(m);}[STAThread]static void Main(){Directory.CreateDirectory("output/office-shapes");using var gallery=new ShapeGalleryPopup();var groups=(List<ShapeGalleryGroup>)typeof(ShapeGalleryPopup).GetField("groups",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(gallery);var types=groups.SelectMany(g=>g.Items).Select(i=>i.ShapeType).Distinct().Where(t=>!t.Contains("Connector")&&!t.Contains("ArrowLine")&&!t.StartsWith("Freeform")&&t!="Line"&&t!="TextBox").ToList();
using var preview=new Bitmap(1000,(int)Math.Ceiling(types.Count/8d)*100);using(var g=Graphics.FromImage(preview)){g.Clear(Color.White);g.SmoothingMode=SmoothingMode.AntiAlias;using var fill=new SolidBrush(Color.FromArgb(68,114,196));using var pen=new Pen(Color.FromArgb(47,85,151),1);using var font=new Font("Segoe UI",7);for(int i=0;i<types.Count;i++){var box=new Rectangle(i%8*125+20,i/8*100+5,85,57);using var path=ShapeRenderer.CreateShapePath(types[i],box);Check(path.PointCount>0,types[i]+" has geometry");g.FillPath(fill,path);g.DrawPath(pen,path);g.DrawString(types[i],font,Brushes.Black,new RectangleF(i%8*125,i/8*100+67,125,32));}}preview.Save("output/office-shapes/presets.png");
var view=new SlidesView();foreach(string type in types){view.StartShapeDrawMode(type);Check(!view.IsScribbleMode&&!view.IsFreeformShapeMode,type+" uses drag creation");view.IsDrawingActive=true;view.ShapeDrawStart=new Point(400,300);view.ShapeDrawCurrent=new Point(620,440);int before=view.ActiveSlide.Shapes.Count;view.HandleMouseUp(new Point(620,440),1100,740);Check(view.ActiveSlide.Shapes.Count==before+1,type+" inserts one shape");var shape=view.SelectedShape;Check(shape.Type==ShapeType.CustomPath&&shape.CustomPath?.PointCount>0&&shape.Name==type,type+" keeps its exact preset");if(type=="ActionButtonForward")Check(shape.ClickActionType==SlideActionType.NextSlide,"Forward navigates next");if(type=="ActionButtonBack")Check(shape.ClickActionType==SlideActionType.PreviousSlide,"Back navigates previous");}
PptxHandler.SavePptx("output/office-shapes/roundtrip.pptx",view.Presentation);var loaded=PptxHandler.LoadPptx("output/office-shapes/roundtrip.pptx");Check(loaded.Slides[0].Shapes.Count==view.ActiveSlide.Shapes.Count,"Every preset survives PPTX roundtrip");foreach(var shape in loaded.Slides[0].Shapes)Check(shape.CustomPath?.PointCount>0,"Imported preset keeps vector geometry");
foreach(string preset in new[]{"actionButtonForwardNext","flowChartInputOutput","flowChartDocument"}){
string file="output/office-shapes/import-"+preset+".pptx";File.Copy("output/office-shapes/roundtrip.pptx",file,true);
using(var zip=System.IO.Compression.ZipFile.Open(file,System.IO.Compression.ZipArchiveMode.Update)){var entry=zip.GetEntry("ppt/slides/slide1.xml");string xml;using(var reader=new StreamReader(entry.Open()))xml=reader.ReadToEnd();xml=new System.Text.RegularExpressions.Regex(@"<a:custGeom>.*?</a:custGeom>",System.Text.RegularExpressions.RegexOptions.Singleline).Replace(xml,"<a:prstGeom prst=\""+preset+"\"><a:avLst/></a:prstGeom>",1);entry.Delete();using var writer=new StreamWriter(zip.CreateEntry("ppt/slides/slide1.xml").Open());writer.Write(xml);}
var imported=PptxHandler.LoadPptx(file).Slides[0].Shapes[0];Check(imported.Type==ShapeType.CustomPath&&imported.CustomPath.PathPoints.Any(p=>(p.X>0&&p.X<1000)||(p.Y>0&&p.Y<1000)),"Imported "+preset+" keeps its actual preset silhouette");
}
Check(loaded.Slides[0].Shapes.Any(s=>s.ClickActionType==SlideActionType.NextSlide),"Action navigation survives PPTX export/import");
Console.WriteLine("PASS: "+types.Count+" editable presets, actual drag creation, action navigation defaults, and PPTX vector roundtrip");}}
